import numpy as np

N = 6  # Board size 6x6
board = np.zeros((N, N), dtype=int) # 0: Empty, 1: Knight, 2: Queen

# --- Knight Logic ---
def is_valid(r, c):
    return 0 <= r < N and 0 <= c < N

def get_knight_moves(r, c):
    moves = []
    for dr, dc in [(1, 2), (1, -2), (-1, 2), (-1, -2), (2, 1), (2, -1), (-2, 1), (-2, -1)]:
        nr, nc = r + dr, c + dc
        if is_valid(nr, nc):
            moves.append((nr, nc))
    return moves

def is_knight_attacked(r, c, knight_positions):
    # Checks if (r, c) is attacked by any knight in knight_positions
    for kr, kc in knight_positions:
        if (r, c) in get_knight_moves(kr, kc):
            return True
    return False

# --- Queen Logic ---
def is_queen_attacked(r, c, queen_positions):
    # Checks if (r, c) is attacked by any queen in queen_positions
    for qr, qc in queen_positions:
        # Same row or column
        if r == qr or c == qc:
            return True
        # Diagonal
        elif abs(r - qr) == abs(c - qc):
            return True
    return False

