                # CRITICAL ASSUMPTION: Horst can ONLY place a knight where it is NOT attacked by a queen.
                if not is_queen_attacked(r, c, queens):
                    available_knights.append((r, c))

    # 2. Determine Queenie's optimal move (Targeting)
    # Queenie wants to choose an empty spot q that maximizes the reduction in future knight availability.

    empty_spots = []
    for r in range(N):
        for c in range(N):
            if board[r, c] == 0:
                empty_spots.append((r, c))

    best_queen_move = None
    max_attacked_potential = -1

    # Heuristic for Queenie: Choose the spot that attacks the maximum number of current potential knight spots.
    for qr, qc in empty_spots:
        potential_targets = 0

        # Check how many currently available (knight-valid AND queen-unattacked) squares 
        # would be attacked by a queen placed at (qr, qc).
        for r_target, c_target in available_knights:
            if abs(r_target - qr) <= N and abs(c_target - qc) <= N: # Range check, always true here
                 if r_target == qr or c_target == qc or abs(r_target - qr) == abs(c_target - qc):
                    potential_targets += 1

        if potential_targets > max_attacked_potential:
            max_attacked_potential = potential_targets
            best_queen_move = (qr, qc)

    return available_knights, best_queen_move


